                                title={player.name}
                                year={year}
                                validYears={activeYears}
                            />
                        </Center>
                    </Grid.Col>
                    <Grid.Col
                        span="content"
                        align="center"
                    >
                        {nextPlayer ? (
                            <PlayerLink
                                player={nextPlayer}
                                year={year}
                                format="right-arrow"
                            />
                        ) : (
                            <Box
                                data-testid="player-next-placeholder"
                                aria-hidden="true"
                            />
                        )}
                    </Grid.Col>
                </Grid>
                <Grid
                    type="container"
                    breakpoints={{
                        xs: '24em',
                        sm: '36em',
                        md: '54em',
                        lg: '74em',
                        xl: '88em',
