1	'use client';
2	
3	import {
4	    Anchor,
5	    Box,
6	    Group,
7	    Image,
8	    Popover,
9	    ScrollAreaAutosize,
10	    Stack,
11	    Text,
12	} from '@mantine/core';
13	import { json } from 'd3-fetch';
14	import { geoMercator, geoPath } from 'd3-geo';
15	import { select } from 'd3-selection';
16	import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
17	import * as topojson from 'topojson-client';
18	import type { GeometryCollection, Topology } from 'topojson-specification';
19	
20	import { CountrySupporterWithPlayerDataType } from '@/types';
21	
22	/**
23	 * Mapping from database country names to their corresponding TopoJSON atlas
24	 * names where they differ. Multiple DB names may map to the same atlas entry
25	 * (e.g. the four UK home nations all map to "United Kingdom").
26	 */
27	const COUNTRY_NAME_MAP: Record<string, string> = {
28	    England: 'United Kingdom',
29	    'Northern Ireland': 'United Kingdom',
30	    Scotland: 'United Kingdom',
31	    Wales: 'United Kingdom',
32	    'Russian Federation': 'Russia',
33	    'Bosnia and Herzegovina': 'Bosnia and Herz.',
34	    'Central African Republic': 'Central African Rep.',
35	    'Dominican Republic': 'Dominican Rep.',
36	    'Equatorial Guinea': 'Eq. Guinea',
37	    Swaziland: 'eSwatini',
38	    'United States': 'United States of America',
39	};
40	
41	/**
42	 * Properties for the {@link PlayerCountryMap} component.
43	 */
44	export interface Props {
45	    /** Array of country supporter entries with player data for highlighting and hover. */
46	    countries: CountrySupporterWithPlayerDataType[];
47	    /** Width of the SVG viewport in pixels. */
48	    width?: number;
49	    /** Height of the SVG viewport in pixels. */
50	    height?: number;
51	}
52	
53	/** Shape of properties on each country feature in the TopoJSON atlas. */
54	interface CountryProperties {
55	    name: string;
56	}
57	
58	/** Fill colour applied to highlighted (supported) countries. */
59	const HIGHLIGHT_FILL = '#228be6';
60	/** Fill colour for countries that are not highlighted. */
61	const DEFAULT_FILL = '#ccc';
62	/** Stroke colour for country borders. */
63	const STROKE_COLOUR = '#fff';
64	/** Stroke width for country borders. */
65	const STROKE_WIDTH = 0.5;
66	/** Maximum height of the scrollable player list inside the hover popover. */
67	const POPOVER_MAX_HEIGHT = 200;
68	/** Size of mugshot thumbnails in the hover popover. */
69	const MUGSHOT_SIZE = 32;
70	/** Delay in ms before closing the popover after mouse leaves a country path. */
71	const CLOSE_DELAY_MS = 200;
72	
73	/**
74	 * Resolves a database country name to its TopoJSON atlas equivalent.
75	 * Returns the mapped name if one exists, or the original name otherwise.
76	 */
77	const toAtlasName = (dbName: string): string =>
78	    COUNTRY_NAME_MAP[dbName] ?? dbName;
79	
80	/**
81	 * A D3-powered world map that highlights countries supported by players and
82	 * shows player mugshots in a popover on hover.
83	 *
84	 * Renders all countries from a TopoJSON world atlas and fills those whose
85	 * names match the supplied supporter entries with an accent colour. When a
86	 * highlighted country is hovered, a popover displays the mugshot and name of
87	 * each supporting player, grouped by their database country name (useful
88	 * when multiple nations share one atlas polygon, e.g. the four UK home
89	 * nations). For countries with many supporters the list is scrollable.
90	 *
91	 * Based on the approach described at
92	 * {@link http://www.d3noob.org/2013/03/a-simple-d3js-map-explained.html}.
93	 */
94	export const PlayerCountryMap = ({
95	    countries,
96	    width = 960,
97	    height = 500,
98	}: Props) => {
99	    const svgRef = useRef<SVGSVGElement>(null);
100	    /** Projected centroids for each highlighted atlas country. */
101	    const centroidsRef = useRef<Map<string, { x: number; y: number }>>(
102	        new Map(),
103	    );
104	    /** Timer handle for the delayed popover close. */
105	    const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
106	    /** Whether the mouse is currently inside the popover dropdown. */
107	    const dropdownHoveredRef = useRef(false);
108	    const [popoverOpen, setPopoverOpen] = useState(false);
109	    const [popoverPos, setPopoverPos] = useState<{ x: number; y: number }>({
110	        x: 0,
111	        y: 0,
112	    });
113	    const [hoveredCountry, setHoveredCountry] = useState<string | null>(null);
114	
115	    /**
116	     * Builds a lookup from lower-cased atlas country name to an array of
117	     * supporters. Multiple DB country names that share the same atlas name
118	     * are grouped together.
119	     */
120	    const supportersByAtlasName = useMemo(() => {
121	        const map = new Map<string, CountrySupporterWithPlayerDataType[]>();
122	        for (const cs of countries) {
123	            const key = toAtlasName(cs.country.name).toLowerCase();
124	            const arr = map.get(key) ?? [];
125	            arr.push(cs);
126	            map.set(key, arr);
127	        }
128	        return map;
129	    }, [countries]);
130	
131	    /**
132	     * Returns the supporters for the currently hovered country, grouped by
133	     * their original database country name for display purposes.
134	     */
135	    const hoveredGroups = useMemo(() => {
136	        if (!hoveredCountry) return [];
137	        /* v8 ignore next -- only countries in supportersByAtlasName trigger hover; get() always returns an array */
138	        const supporters = supportersByAtlasName.get(hoveredCountry) ?? [];
139	        const grouped = new Map<string, CountrySupporterWithPlayerDataType[]>();
140	        for (const s of supporters) {
141	            const key = s.country.name;
142	            const arr = grouped.get(key) ?? [];
143	            arr.push(s);
144	            grouped.set(key, arr);
145	        }
146	        return Array.from(grouped.entries());
147	    }, [hoveredCountry, supportersByAtlasName]);
148	
149	    /** Cancels any pending delayed close. */
150	    const cancelClose = useCallback(() => {
151	        if (closeTimerRef.current) {
152	            clearTimeout(closeTimerRef.current);
153	            closeTimerRef.current = null;
154	        }
155	    }, []);
156	
157	    /** Schedules a delayed popover close unless the dropdown is hovered. */
158	    const scheduleClose = useCallback(() => {
159	        cancelClose();
160	        closeTimerRef.current = setTimeout(() => {
161	            /* c8 ignore next — onMouseEnter always cancels the timer before setting dropdownHoveredRef; the timer can only fire while the flag is false */
162	            if (!dropdownHoveredRef.current) {
163	                setPopoverOpen(false);
164	                setHoveredCountry(null);
165	            }
166	        }, CLOSE_DELAY_MS);
167	    }, [cancelClose]);
168	
169	    /**
170	     * Handles mouse-enter on a highlighted country path. Anchors the popover
171	     * to the country's projected centroid for a stable position.
172	     */
173	    const handleMouseEnter = useCallback(
174	        (atlasName: string) => {
175	            cancelClose();
176	            const lowerName = atlasName.toLowerCase();
177	            const centroid = centroidsRef.current.get(lowerName);
178	            /* v8 ignore next -- centroid is always pre-computed before a D3 mouseenter can fire */
179	            if (centroid) {
180	                setPopoverPos(centroid);
181	            }
182	            setHoveredCountry(lowerName);
183	            setPopoverOpen(true);
184	        },
185	        [cancelClose],
186	    );
187	
188	    /** Handles mouse-leave on a highlighted country path. */
189	    const handleMouseLeave = useCallback(() => {
190	        scheduleClose();
191	    }, [scheduleClose]);
192	
193	    useEffect(() => {
194	        /* c8 ignore next — svgRef is always attached before effects run; the null path is a defensive guard only */
195	        if (!svgRef.current) return;
196	
197	        const svg = select(svgRef.current);
198	        svg.selectAll('*').remove();
199	
200	        const projection = geoMercator()
201	            .center([0, 20])
202	            .scale(width / 6.5)
203	            .translate([width / 2, height / 2]);
204	
205	        const path = geoPath().projection(projection);
206	
207	        const g = svg.append('g');
208	
209	        const supportedNames = new Set(supportersByAtlasName.keys());
210	
211	        void json<Topology>('/countries-110m.json').then((topology) => {
212	            if (!topology) return undefined;
213	
214	            const geojson = topojson.feature(
215	                topology,
216	                topology.objects.countries as GeometryCollection,
217	            );
218	
219	            type CountryFeature = GeoJSON.Feature<
220	                GeoJSON.Geometry,
221	                CountryProperties
222	            >;
223	            const features = geojson.features as CountryFeature[];
224	
225	            /* Pre-compute projected centroids for highlighted countries so
226	               the popover can be anchored to a stable position. */
227	            const newCentroids = new Map<string, { x: number; y: number }>();
228	            for (const f of features) {
229	                const name = (f.properties?.name ?? '').toLowerCase();
230	                if (supportedNames.has(name)) {
231	                    const [cx, cy] = path.centroid(f);
232	                    newCentroids.set(name, { x: cx, y: cy });
233	                }
234	            }
235	            centroidsRef.current = newCentroids;
236	
237	            g.selectAll<SVGPathElement, CountryFeature>('path')
238	                .data(features)
239	                .enter()
240	                .append('path')
241	                .attr('d', path)
242	                .attr('fill', (d) => {
243	                    const name = (d.properties?.name ?? '').toLowerCase();
244	                    return supportedNames.has(name)
245	                        ? HIGHLIGHT_FILL
246	                        : DEFAULT_FILL;
247	                })
248	                .attr('stroke', STROKE_COLOUR)
249	                .attr('stroke-width', STROKE_WIDTH)
250	                .on('mouseenter', function (_event: MouseEvent, d) {
251	                    const name = (d.properties?.name ?? '').toLowerCase();
252	                    if (supportedNames.has(name)) {
253	                        handleMouseEnter(name);
254	                    }
255	                })
256	                .on('mouseleave', function () {
257	                    handleMouseLeave();
258	                });
259	
260	            return undefined;
261	        });
262	    }, [
263	        countries,
264	        width,
265	        height,
266	        supportersByAtlasName,
267	        handleMouseEnter,
268	        handleMouseLeave,
269	    ]);
270	
271	    return (
272	        <Box
273	            pos="relative"
274	            data-testid="player-country-map"
275	        >
276	            <svg
277	                ref={svgRef}
278	                width={width}
279	                height={height}
280	            />
281	            <Popover
282	                opened={popoverOpen}
283	                position="bottom"
284	                withArrow
285	                shadow="md"
286	                withinPortal={false}
287	            >
288	                <Popover.Target>
289	                    <Box
290	                        pos="absolute"
291	                        left={popoverPos.x}
292	                        top={popoverPos.y}
293	                        w={1}
294	                        h={1}
295	                        pe="none"
296	                    />
297	                </Popover.Target>
298	                <Popover.Dropdown
299	                    data-testid="country-popover-dropdown"
300	                    onMouseEnter={() => {
301	                        dropdownHoveredRef.current = true;
302	                        cancelClose();
303	                    }}
304	                    onMouseLeave={() => {
305	                        dropdownHoveredRef.current = false;
306	                        scheduleClose();
307	                    }}
308	                    pe="auto"
309	                >
310	                    <ScrollAreaAutosize mah={POPOVER_MAX_HEIGHT}>
311	                        <Stack gap="xs">
312	                            {hoveredGroups.map(([countryName, supporters]) => (
313	                                <Stack
314	                                    key={countryName}
315	                                    gap={4}
316	                                >
317	                                    <Text
318	                                        size="xs"
319	                                        fw={700}
320	                                    >
321	                                        {countryName}
322	                                    </Text>
323	                                    {supporters.map((s) => (
324	                                        <Anchor
325	                                            key={s.playerId}
326	                                            href={`/footy/player/${s.playerId}`}
327	                                            underline="never"
328	                                        >
329	                                            <Group
330	                                                gap="xs"
331	                                                wrap="nowrap"
332	                                            >
333	                                                <Image
334	                                                    src={`/api/footy/player/${s.playerId}/mugshot`}
335	                                                    alt={
336	                                                        s.player.name ??
337	                                                        `Player ${s.playerId}`
338	                                                    }
339	                                                    w={MUGSHOT_SIZE}
340	                                                    h={MUGSHOT_SIZE}
341	                                                    radius="xl"
342	                                                />
343	                                                <Text size="sm">
344	                                                    {s.player.name ??
345	                                                        `Player ${s.playerId}`}
346	                                                </Text>
347	                                            </Group>
348	                                        </Anchor>
349	                                    ))}
350	                                </Stack>
351	                            ))}
352	                        </Stack>
353	                    </ScrollAreaAutosize>
354	                </Popover.Dropdown>
355	            </Popover>
356	        </Box>
357	    );
358	};
